import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { judgeStaged } from '../server/gemma.js';

const DIR = join(import.meta.dirname, 'fixtures', 'real');

/**
 * The judge against real photographs.
 *
 * Every other fixture in this project is a gradient generated by a Python
 * script. Those prove the model discriminates, but they cannot prove it
 * handles the noise, texture and lighting of a real camera image — and one
 * of them is correctly flagged as a screen photo precisely because it is a
 * flat computer-generated graphic.
 *
 * These hit the live model, so they are skipped when Ollama is not running.
 * They are slow on purpose: this is the claim the whole product rests on.
 */

const MINUTE = 60_000;

async function ollamaUp() {
  try {
    const res = await fetch('http://localhost:11434/api/version', {
      signal: AbortSignal.timeout(1500),
    });
    return res.ok;
  } catch {
    return false;
  }
}

const judge = async (file, task) =>
  judgeStaged({ imageB64: (await readFile(join(DIR, file))).toString('base64'), task });

const PEACE = { check: 'a distant horizon or open outdoor space is visible AND a hand makes a peace sign' };

/**
 * The central cheat: lean over, photograph the garden through the glass,
 * never leave the chair. If this passes, the product is just a slow
 * dismissible reminder.
 */
test('rejects a photo taken through a window', { timeout: 2 * MINUTE }, async (t) => {
  if (!(await ollamaUp())) return t.skip('Ollama is not running');

  const v = await judge('through-window.jpg', PEACE);

  assert.equal(v.ok, false, 'a window photo must never unlock the browser');
  assert.equal(v.stage, 'glass', `expected rejection at the glass gate, got ${v.stage}`);
  assert.match(v.reason, /window|glass|frame/i, 'the reason must say what was seen');
  assert.match(v.reason, /outside/i, 'and what to do about it');
});

test('rejects an indoor photo at the first gate', { timeout: 2 * MINUTE }, async (t) => {
  if (!(await ollamaUp())) return t.skip('Ollama is not running');

  const v = await judge('indoor-desk.jpg', PEACE);

  assert.equal(v.ok, false);
  assert.equal(v.stage, 'outdoor', 'the cheapest rejection should also be the first');
});

/**
 * The other direction, which matters just as much: a real outdoor photo must
 * not be rejected as a screen or a window. A product that refuses genuine
 * compliance gets uninstalled faster than one that is too lenient.
 */
test('accepts a genuine outdoor photo through every authenticity gate', { timeout: 2 * MINUTE }, async (t) => {
  if (!(await ollamaUp())) return t.skip('Ollama is not running');

  const v = await judge('outdoor-hikers.jpg', PEACE);

  assert.equal(v.outdoor, true, 'a real outdoor photo must read as outdoors');
  assert.equal(v.through_glass, false, 'and not be mistaken for a window shot');
  assert.equal(v.screen_photo, false, 'and not be mistaken for a photo of a screen');

  // It should still fail the task, because nobody in it is making a peace
  // sign — that is the gesture check working, not a false rejection.
  assert.equal(v.stage, 'task');
});
